import subprocess
code='import pathlib,subprocess,json,time\nout=pathlib.Path(\'/home/data/wangyue/artifacts/venturi-token16-graph-probe-v9\');out.mkdir();p=out/\'worker.py\';p.write_text(\'import pathlib,subprocess,os,time,json,hashlib,signal,traceback\\nroot=pathlib.Path(\\\'/home/data/wangyue\\\');src=root/\\\'repos/codex-build/Venturi/token16-src-v2\\\';out=root/\\\'artifacts/venturi-token16-graph-probe-v9\\\';py=str(root/\\\'repos/codex-build/.venvs/b2-v100/bin/python\\\')\\nenv=os.environ.copy();env.update(CUDA_VISIBLE_DEVICES=\\\'1,0\\\',PYTHONPATH=str(root/\\\'repos/codex-build/Venturi/v100-tp-diagnostics-v2/python-deps\\\')+\\\':\\\'+str(src/\\\'src\\\')+\\\':\\\'+str(src/\\\'tests\\\'),OMP_NUM_THREADS=\\\'4\\\',MKL_NUM_THREADS=\\\'4\\\',PYTEST_DISABLE_PLUGIN_AUTOLOAD=\\\'1\\\')\\ndef stop(p):\\n if p.poll() is None:\\n  os.killpg(p.pid,signal.SIGTERM)\\n  try:p.wait(timeout=20)\\n  except subprocess.TimeoutExpired:os.killpg(p.pid,signal.SIGKILL);p.wait()\\ndef run(cmd,name,timeout=300):\\n (out/(name+\\\'.command.json\\\')).write_text(json.dumps(cmd,indent=2)+\\\'\\\\n\\\')\\n with (out/name).open(\\\'wb\\\') as log:\\n  p=subprocess.Popen(cmd,cwd=src,env=env,stdout=log,stderr=subprocess.STDOUT,start_new_session=True)\\n  try:rc=p.wait(timeout=timeout)\\n  except BaseException:stop(p);raise\\n  if rc:raise RuntimeError(f\\\'Owned command exited {rc}: {name}\\\')\\ntry:\\n gate=root/\\\'artifacts/venturi-token16-staged-final-v8\\\';deadline=time.monotonic()+3600\\n while not (gate/\\\'exit-code.txt\\\').exists():\\n  pid=json.loads((gate/\\\'process.json\\\').read_text())[\\\'pid\\\'];c=pathlib.Path(f\\\'/proc/{pid}/cmdline\\\');assert c.exists() and str(gate/\\\'worker.py\\\').encode() in c.read_bytes();assert time.monotonic()<deadline,\\\'Observation timeout only; revalidate original handle\\\';time.sleep(15)\\n assert (gate/\\\'exit-code.txt\\\').read_text().strip()==\\\'0\\\'\\n script=\\\'"""Probe two-GPU host-bridge graph capture; not a model or serving benchmark."""\\\\n\\\\nimport argparse\\\\nimport ctypes as C\\\\nimport hashlib\\\\nimport json\\\\nfrom pathlib import Path\\\\nimport resource\\\\nfrom time import perf_counter\\\\n\\\\nimport torch\\\\nfrom venturi.ops import CudaBackend, Q8RowSplitWeight, prepare_q8_dp4a\\\\n\\\\n\\\\nclass CudaError(RuntimeError):\\\\n    def __init__(self, call, code, name):\\\\n        self.code, self.name = code, name\\\\n        super().__init__(f"{call}: {name} ({code})")\\\\n\\\\n\\\\nclass Runtime:\\\\n    def __init__(self):\\\\n        self.dll = C.CDLL("/usr/local/cuda/lib64/libcudart.so.12")\\\\n        v, i, u = C.c_void_p, C.c_int, C.c_uint\\\\n        signatures = {\\\\n            "cudaSetDevice": [i],\\\\n            "cudaStreamCreateWithFlags": [C.POINTER(v), u],\\\\n            "cudaEventCreateWithFlags": [C.POINTER(v), u],\\\\n            "cudaEventRecord": [v, v],\\\\n            "cudaStreamWaitEvent": [v, v, u],\\\\n            "cudaMemcpyAsync": [v, v, C.c_size_t, i, v],\\\\n            "cudaStreamSynchronize": [v],\\\\n            "cudaStreamBeginCapture": [v, i],\\\\n            "cudaStreamEndCapture": [v, C.POINTER(v)],\\\\n            "cudaGraphInstantiateWithFlags": [C.POINTER(v), v, C.c_ulonglong],\\\\n            "cudaGraphLaunch": [v, v],\\\\n            "cudaGraphDestroy": [v],\\\\n            "cudaGraphExecDestroy": [v],\\\\n            "cudaEventDestroy": [v],\\\\n            "cudaStreamDestroy": [v],\\\\n            "cudaGetLastError": [],\\\\n        }\\\\n        for name, args in signatures.items():\\\\n            fn = getattr(self.dll, name)\\\\n            fn.argtypes, fn.restype = args, i\\\\n        self.dll.cudaGetErrorName.argtypes = [i]\\\\n        self.dll.cudaGetErrorName.restype = C.c_char_p\\\\n\\\\n    def call(self, name, *args):\\\\n        code = getattr(self.dll, name)(*args)\\\\n        if code:\\\\n            raise CudaError(name, code, self.dll.cudaGetErrorName(code).decode())\\\\n\\\\n\\\\ndef cpu():\\\\n    r = resource.getrusage(resource.RUSAGE_SELF)\\\\n    return r.ru_utime + r.ru_stime\\\\n\\\\n\\\\ndef main():\\\\n    p = argparse.ArgumentParser(description=__doc__)\\\\n    p.add_argument("--library", required=True)\\\\n    p.add_argument("--output", required=True)\\\\n    a = p.parse_args()\\\\n    torch.set_num_threads(4)\\\\n    if torch.cuda.device_count() != 2:\\\\n        raise ValueError("Exactly two explicitly selected CUDA devices required")\\\\n    rt = Runtime()\\\\n    streams, events, external = [], [], []\\\\n    graph, executable = C.c_void_p(), C.c_void_p()\\\\n    report = dict(\\\\n        scope=__doc__,\\\\n        completed=False,\\\\n        capture_supported=False,\\\\n        tokens=3,\\\\n        k=128,\\\\n        output_rows_per_device=17,\\\\n        logical_requests=None,\\\\n        model_quality_qualified=False,\\\\n        physical_gpus=[1, 0],\\\\n        transport="pinned host, both ownership fences",\\\\n        library_sha256=hashlib.sha256(Path(a.library).read_bytes()).hexdigest(),\\\\n        achieved_hardware_counters=None,\\\\n        trials=[],\\\\n    )\\\\n    capturing = False\\\\n    try:\\\\n        for device in [0, 1]:\\\\n            rt.call("cudaSetDevice", device)\\\\n            stream, event = C.c_void_p(), C.c_void_p()\\\\n            rt.call("cudaStreamCreateWithFlags", C.byref(stream), 1)\\\\n            streams.append(stream)\\\\n            rt.call("cudaEventCreateWithFlags", C.byref(event), 2)\\\\n            events.append(event)\\\\n            external.append(torch.cuda.ExternalStream(stream.value, device=device))\\\\n        backend = CudaBackend(a.library)\\\\n        generator = torch.Generator().manual_seed(843)\\\\n        weights = [\\\\n            Q8RowSplitWeight(\\\\n                torch.randint(\\\\n                    -127, 128, (17, 128), dtype=torch.int8, generator=generator\\\\n                ),\\\\n                torch.full((17, 4), 0.01, dtype=torch.float16),\\\\n                128,\\\\n            )\\\\n            for _ in range(2)\\\\n        ]\\\\n        resident = [\\\\n            backend.upload_linear(w, dtype=torch.float16, device=f"cuda:{i}")\\\\n            for i, w in enumerate(weights)\\\\n        ]\\\\n        plans = [\\\\n            prepare_q8_dp4a(r, tokens=3, residual_compensation=True) for r in resident\\\\n        ]\\\\n        xs = [\\\\n            torch.empty((3, 128), dtype=torch.float16, device=f"cuda:{i}")\\\\n            for i in [0, 1]\\\\n        ]\\\\n        ys = [\\\\n            torch.empty((3, 17), dtype=torch.float16, device=f"cuda:{i}")\\\\n            for i in [0, 1]\\\\n        ]\\\\n        work = [\\\\n            torch.empty(p.workspace_bytes, dtype=torch.uint8, device=f"cuda:{i}")\\\\n            for i, p in enumerate(plans)\\\\n        ]\\\\n        inbound = torch.empty((3, 128), dtype=torch.float16, pin_memory=True)\\\\n        outbound = torch.empty((3, 17), dtype=torch.float16, pin_memory=True)\\\\n        gathered = torch.empty((3, 17), dtype=torch.float16, device="cuda:0")\\\\n        xcpu = torch.randn((3, 128), generator=generator).half()\\\\n        xs[0].copy_(xcpu)\\\\n        torch.cuda.synchronize(0)\\\\n        torch.cuda.synchronize(1)\\\\n\\\\n        def flow():\\\\n            rt.call("cudaSetDevice", 0)\\\\n            rt.call(\\\\n                "cudaMemcpyAsync",\\\\n                inbound.data_ptr(),\\\\n                xs[0].data_ptr(),\\\\n                inbound.numel() * 2,\\\\n                2,\\\\n                streams[0],\\\\n            )\\\\n            rt.call("cudaEventRecord", events[0], streams[0])\\\\n            rt.call("cudaSetDevice", 1)\\\\n            rt.call("cudaStreamWaitEvent", streams[1], events[0], 0)\\\\n            rt.call(\\\\n                "cudaMemcpyAsync",\\\\n                xs[1].data_ptr(),\\\\n                inbound.data_ptr(),\\\\n                inbound.numel() * 2,\\\\n                1,\\\\n                streams[1],\\\\n            )\\\\n            with torch.cuda.device(1), torch.cuda.stream(external[1]):\\\\n                plans[1].run(xs[1], out=ys[1], workspace=work[1])\\\\n            rt.call(\\\\n                "cudaMemcpyAsync",\\\\n                outbound.data_ptr(),\\\\n                ys[1].data_ptr(),\\\\n                outbound.numel() * 2,\\\\n                2,\\\\n                streams[1],\\\\n            )\\\\n            rt.call("cudaEventRecord", events[1], streams[1])\\\\n            rt.call("cudaSetDevice", 0)\\\\n            with torch.cuda.stream(external[0]):\\\\n                plans[0].run(xs[0], out=ys[0], workspace=work[0])\\\\n            rt.call("cudaStreamWaitEvent", streams[0], events[1], 0)\\\\n            rt.call(\\\\n                "cudaMemcpyAsync",\\\\n                gathered.data_ptr(),\\\\n                outbound.data_ptr(),\\\\n                outbound.numel() * 2,\\\\n                1,\\\\n                streams[0],\\\\n            )\\\\n\\\\n        for _ in range(3):\\\\n            flow()\\\\n            rt.call("cudaStreamSynchronize", streams[0])\\\\n        expected = [ys[0].cpu(), ys[1].cpu()]\\\\n        assert torch.equal(\\\\n            gathered.cpu().view(torch.uint8), expected[1].view(torch.uint8)\\\\n        )\\\\n        rt.call("cudaSetDevice", 0)\\\\n        rt.call("cudaStreamBeginCapture", streams[0], 0)\\\\n        capturing = True\\\\n        flow()\\\\n        rt.call("cudaStreamEndCapture", streams[0], C.byref(graph))\\\\n        capturing = False\\\\n        rt.call("cudaGraphInstantiateWithFlags", C.byref(executable), graph, 0)\\\\n        report["capture_supported"] = True\\\\n        for repeat in range(3):\\\\n            for mode in ["eager", "graph"] if repeat % 2 == 0 else ["graph", "eager"]:\\\\n                start, used = perf_counter(), cpu()\\\\n                for _ in range(20):\\\\n                    if mode == "graph":\\\\n                        rt.call("cudaGraphLaunch", executable, streams[0])\\\\n                    else:\\\\n                        flow()\\\\n                rt.call("cudaStreamSynchronize", streams[0])\\\\n                report["trials"].append(\\\\n                    dict(\\\\n                        repeat=repeat,\\\\n                        mode=mode,\\\\n                        calls=20,\\\\n                        wall_seconds=perf_counter() - start,\\\\n                        cpu_core_seconds=cpu() - used,\\\\n                    )\\\\n                )\\\\n                assert torch.equal(\\\\n                    ys[0].cpu().view(torch.uint8), expected[0].view(torch.uint8)\\\\n                )\\\\n                assert torch.equal(\\\\n                    gathered.cpu().view(torch.uint8), expected[1].view(torch.uint8)\\\\n                )\\\\n        # Input addresses are fixed, values are not: changing them must affect\\\\n        # both devices on replay without a stale host-bridge read.\\\\n        xs[0].zero_()\\\\n        torch.cuda.synchronize(0)\\\\n        rt.call("cudaGraphLaunch", executable, streams[0])\\\\n        rt.call("cudaStreamSynchronize", streams[0])\\\\n        assert not ys[0].any() and not gathered.any()\\\\n        xs[0].copy_(xcpu)\\\\n        torch.cuda.synchronize(0)\\\\n        rt.call("cudaGraphLaunch", executable, streams[0])\\\\n        rt.call("cudaStreamSynchronize", streams[0])\\\\n        assert torch.equal(\\\\n            gathered.cpu().view(torch.uint8), expected[1].view(torch.uint8)\\\\n        )\\\\n        report["exact_bytes_and_mutable_input_replay"] = True\\\\n        report["model_dynamic_kv_gdn_positions_tested"] = False\\\\n    except CudaError as error:\\\\n        report["cuda_error"] = dict(\\\\n            code=error.code, name=error.name, message=str(error)\\\\n        )\\\\n        if "StreamCapture" not in error.name:\\\\n            raise\\\\n        report["capture_supported"] = False\\\\n    finally:\\\\n        rt.dll.cudaSetDevice(0)\\\\n        if capturing:\\\\n            rt.dll.cudaStreamEndCapture(streams[0], C.byref(graph))\\\\n            rt.dll.cudaGetLastError()\\\\n        if executable.value:\\\\n            rt.dll.cudaGraphExecDestroy(executable)\\\\n        if graph.value:\\\\n            rt.dll.cudaGraphDestroy(graph)\\\\n        for device, stream in enumerate(streams):\\\\n            rt.dll.cudaSetDevice(device)\\\\n            rt.dll.cudaStreamSynchronize(stream)\\\\n            if device < len(events):\\\\n                rt.dll.cudaEventDestroy(events[device])\\\\n            rt.dll.cudaStreamDestroy(stream)\\\\n    report["completed"] = True\\\\n    Path(a.output).write_text(json.dumps(report, indent=2) + "\\\\\\\\n")\\\\n    print(json.dumps(report))\\\\n\\\\n\\\\nif __name__ == "__main__":\\\\n    main()\\\\n\\\'\\n assert hashlib.sha256(script.encode()).hexdigest()==\\\'a66ed96d8d38f82712cae227b0bd169a7f6b5556e9ccc602de2d1a4842ea3936\\\'\\n (out/\\\'probe.py\\\').write_text(script)\\n library=str(root/\\\'artifacts/venturi-batched-mtp-model-v2/build/e94e01699eaad5b0/libventuri_blocks.so\\\')\\n samplers=[];handles=[]\\n try:\\n  for device in [1,0]:\\n   f=(out/f\\\'gpu-{device}-samples.csv\\\').open(\\\'wb\\\');handles.append(f)\\n   samplers.append(subprocess.Popen([\\\'nvidia-smi\\\',\\\'-i\\\',str(device),\\\'--query-gpu=timestamp,utilization.gpu,utilization.memory,memory.used,power.draw,temperature.gpu,clocks.sm,clocks.mem\\\',\\\'--format=csv,noheader,nounits\\\',\\\'-lms\\\',\\\'100\\\'],stdout=f,stderr=subprocess.STDOUT,start_new_session=True))\\n  run([py,str(out/\\\'probe.py\\\'),\\\'--library\\\',library,\\\'--output\\\',str(out/\\\'report.json\\\')],\\\'probe.log\\\',timeout=180)\\n finally:\\n  for p in samplers:stop(p)\\n  for f in handles:f.close()\\n (out/\\\'counter-policy.txt\\\').write_text(next(s for s in pathlib.Path(\\\'/proc/driver/nvidia/params\\\').read_text().splitlines() if \\\'RmProfilingAdminOnly\\\' in s)+\\\'\\\\n\\\')\\n run([\\\'nvidia-smi\\\',\\\'--query-gpu=index,name,memory.used,memory.free,utilization.gpu\\\',\\\'--format=csv,noheader\\\'],\\\'gpu-after.txt\\\')\\n (out/\\\'completed.json\\\').write_text(json.dumps(dict(completed=True,script_sha256=hashlib.sha256(script.encode()).hexdigest(),scope=\\\'Transport/projection graph feasibility only, no model or serving qualification.\\\',ended_unix=time.time()),indent=2)+\\\'\\\\n\\\');rc=0\\nexcept BaseException:(out/\\\'failure.txt\\\').write_text(traceback.format_exc());rc=1\\n(out/\\\'exit-code.txt\\\').write_text(str(rc)+\\\'\\\\n\\\');raise SystemExit(rc)\\n\')\nwith (out/\'worker.log\').open(\'xb\') as log:proc=subprocess.Popen([\'python3\',str(p)],stdin=subprocess.DEVNULL,stdout=log,stderr=log,start_new_session=True)\nr=dict(pid=proc.pid,started_unix=time.time());(out/\'process.json\').write_text(json.dumps(r,indent=2));print(json.dumps(r))\n'
